// План specs/admin-plans.md, 1.9 (кейс AP-06, комбинация). Только чтение. @prod-safe
// Статус и план «בדיקה» на проде меняются (trial до 11.10.2026) — берём их из её строки, не зашиваем.
import { test, expect } from '@playwright/test';
import { setLanguage, openPlansTab, TARGET_EMAIL, TARGET_NAME } from './plans-helpers';
import { accountRows, loadedRowCount, searchBox, filterControl, selectFilter, cellValue, columnValues, expectColumnEqualsOrEmpty, expectAllRowsContain, FILTER, EMPTY_EN } from './plans-read-helpers';

test.use({ storageState: '../auth/admin.json' });

test.describe('Admin Panel — Plans', () => {
  test('Status filter combined with search and plan filter shows the intersection #ca557707 @desktop @prod-safe', async ({ page }) => {
    await setLanguage(page, 'en');
    await openPlansTab(page);
    await loadedRowCount(page);

    // Текущие статус и план «בדיקה»
    await searchBox(page).fill('wojeg');
    const target = accountRows(page).filter({ hasText: TARGET_EMAIL });
    await expect(target).toHaveCount(1);
    await expect(target).toContainText(TARGET_NAME);
    const targetStatus = await cellValue(page, target, 'Subscription status'); // на 04.10 — «Trial»
    const targetPlan = await cellValue(page, target, 'Plan');
    const status = filterControl(page, FILTER.statuses);
    const plan = filterControl(page, FILTER.plans);

    // Шаг 2: поиск + статус «בדיקה» → она видна, все строки с этим статусом и содержат «wojeg»
    await selectFilter(page, status, targetStatus);
    await expect(target).toBeVisible();
    await expectColumnEqualsOrEmpty(page, 'Subscription status', targetStatus);
    await expectAllRowsContain(page, 'wojeg');

    // Шаг 3: поиск + «Free» → только Free и «wojeg», или пусто
    await selectFilter(page, status, 'Free');
    await expectColumnEqualsOrEmpty(page, 'Subscription status', 'Free');
    if (!(await page.getByText(EMPTY_EN, { exact: true }).isVisible())) {
      await expectAllRowsContain(page, 'wojeg');
    }
    if (targetStatus !== 'Free') await expect(target).toHaveCount(0);

    // Шаг 4: все статусы + план «בדיקה» → она видна, все строки с этим планом
    await selectFilter(page, status, 'All statuses');
    await selectFilter(page, plan, targetPlan);
    await expect(target).toBeVisible();
    await expectColumnEqualsOrEmpty(page, 'Plan', targetPlan);
    expect((await columnValues(page, 'Plan')).length).toBeGreaterThan(0);
  });
});
